add_filter( 'woocommerce_product_tabs', 'perfectpixel_remove_product_tabs', 98 );

function perfectpixel_remove_product_tabs( $tabs ) {
	$remove = array(
		'description'            => '{{remove_tab_description}}',
		'additional_information' => '{{remove_tab_additional}}',
		'reviews'                => '{{remove_tab_reviews}}',
	);
	foreach ( $remove as $key => $flag ) {
		if ( 'yes' === $flag ) {
			unset( $tabs[ $key ] );
		}
	}
	return $tabs;
}
